int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    // n=1 时只需 1 种；否则答案就是偶数个数 = n/2（向下取整）
    cout << (n == 1 ? 1 : n / 2) << "\n";
    return 0;
}
```

